import com.google.common.escape.*;
import java.util.*;

public class MapTest2 {
  public static void main(String[] a) {
    // multi-entry map exercised through ArrayBasedCharEscaper (uses createReplacementArray)
    Escaper e = Escapers.builder()
        .addEscape('&', "&amp;")
        .addEscape('<', "&lt;")
        .addEscape('>', "&gt;")
        .addEscape('"', "&quot;")
        .build();
    String in = "a&b<c>d\"e plain & <again>";
    String out = e.escape(in);
    String exp = in.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");
    check("multi-entry", out.equals(exp));

    // shared ArrayBasedEscaperMap reused by two escapers
    Map<Character,String> m = new HashMap<>();
    m.put('x', "[X]"); m.put('z', "[Z]");
    ArrayBasedEscaperMap shared = ArrayBasedEscaperMap.create(m);
    Escaper e1 = new ArrayBasedCharEscaper(shared, (char)0, Character.MAX_VALUE) {
      protected char[] escapeUnsafe(char c){ return null; }
    };
    check("shared map", e1.escape("xyzx").equals("[X]y[Z][X]"));

    // empty map -> EMPTY_REPLACEMENT_ARRAY path, no escaping
    Escaper e2 = Escapers.builder().build();
    check("empty map", e2.escape("nothing here").equals("nothing here"));

    // single high-codepoint-ish key to test max+1 sizing
    Escaper e3 = Escapers.builder().addEscape('~', "TILDE").build();
    check("single key", e3.escape("a~b").equals("aTILDEb"));
    System.out.println("ALL PASS");
  }
  static void check(String n, boolean ok){ if(!ok){System.out.println("FAIL: "+n); System.exit(1);} else System.out.println("ok: "+n);}
}
EOF
cd /tmp/esc
javac -cp out_jre -d . MapTest2.java && java -cp out_jre:. MapTest2; echo "TEST EXIT=$?"

